@pytest.mark.parametrize("test_case", [
    pytest.param(tc, id=f"{tc['scenario']} (petId: {tc['petId']}, expectedCode: {tc['statusCode']})")
    for tc in json.load(open(os.path.join(os.path.dirname(__file__), "pet_petId_uploadImage.json"), "r"))
])
def test_upload_image(api_helper, valid_api_key, test_case):
    """
    Test the POST /pet/{petId}/uploadImage endpoint for multiple scenarios.

    This test covers different `petId`, `additionalMetadata`, and possible response codes to validate
    API behavior under various conditions.
    """
    endpoint = f"pet/{test_case['petId']}/uploadImage"

    # Test parameters
    params = {"additionalMetadata": test_case["additionalMetadata"]} if test_case["additionalMetadata"] else {}

    # Headers
    headers = {
        "Authorization": f"Bearer {valid_api_key}",
        "Content-Type": "application/octet-stream",
    }

    # Test payload (binary)
    image_path = os.path.join(os.path.dirname(__file__), "testdata", "sample_image.png")
    files = {"file": open(image_path, "rb")} if test_case["statusCode"] == 200 else None

    # Make the API request
    response = api_helper.make_request(endpoint, params=params, headers=headers, method="POST", files=files)

    # Assert the HTTP status code
    assert response.status_code == test_case["statusCode"], (
        f"Expected status code {test_case['statusCode']} but got {response.status_code}. "
        f"Scenario: {test_case['scenario']}"
    )

    # Additional validations for success case
    if response.status_code == 200:
        response_json = response.json()
        assert "code" in response_json, "Response JSON is missing 'code' field."
        assert "type" in response_json, "Response JSON is missing 'type' field."
        assert "message" in response_json, "Response JSON is missing 'message' field."
        assert str(test_case["petId"]) in response_json["message"], f"PetId {test_case['petId']} not found in response message."

    # Handle error scenarios
    elif response.status_code in {400, 404, 500}:
        assert 'message' in response.text, f"No error message returned for scenario: {test_case['scenario']}."

    # Close file pointer if opened
    if files:
        files["file"].close()


